
$("#studentSelect").change(function() {
      let student = $("#studentSelect").val(); 
      if(student){
        const studentName = $(this).find(':selected').text();
        read(studentName);
      }
  
});

//  read();
function read(studentName) {
    $("resultviews_Table tbody").html('');

    let sendingData = {
      
        "first_name": studentName ,
        "action" : "result_read"
    };

    $.ajax({
        method: "POST",
        dataType: "JSON",
        url: "../APi/resultviews.php",
        data: sendingData,
        success: function(data) {
            let status = data.status;
            let response = data.data;
            let tr = '';

            if (status) {
            
                // semester_name();
                        
                // subject_name();   
                response.forEach(itm => {
                    tr += "<tr>";
                    for (let i in itm) {
                        tr += `<td>${itm[i]}</td>`;
                    }
                    // tr += `<td>
                    //             <button class="btn_upda"> 
                    //                 <a class="updete_cl" update_id="${itm['result_id']}">
                    //                     <span class="material-symbols-outlined" style="color:#fff;background-color:var(--base-clr); font-size: xx-large; font-weight: bold; border-radius: 5px;">
                    //                         edit
                    //                     </span>
                    //                 </a>
                    //             </button> 
                    //             &nbsp;&nbsp;
                    //             <a class="delete_cl" delete_id="${itm['result_id']}">
                    //                 <span class="material-symbols-outlined" style="color:#fff;background-color:red;font-size: xx-large; font-weight: bold; border-radius: 5px;">
                    //                     delete
                    //                 </span>
                    //             </a>
                    //         </td>`;
                    // tr += '</tr>';
                });

                $("#resultviews_Table tbody").append(tr);
            } else {
                console.log("error", response);
            }
        },
        error: function(data) {
            console.log(data);
        }
    });
}





